def decide(observation, tools):
    match_scores = tools.match()
    frame = 1 if match_scores[1] > match_scores[0] else 0

    # Use point data to validate lateral position consistency
    point_data = tools.point()
    if point_data[0] is None and point_data[1] is None:
        # No point detected, fall back to match
        return frame, "right" if observation["views"][frame]["heading"] > 0 else "left", {"heading": observation["views"][frame]["heading"]}

    # Check if point is consistent with forward_of_end_m and right_of_end_m
    # If one point is valid, use the frame with better point alignment
    # We assume the target is in front, so point should be near center in vertical
    # Use the frame where the point is present and heading is positive
    valid_frame = -1
    for f in [0, 1]:
        p = point_data[f]
        if p is not None:
            valid_frame = f
            break

    if valid_frame == -1:
        return frame, "right" if observation["views"][frame]["heading"] > 0 else "left", {"heading": observation["views"][frame]["heading"]}

    # Use the frame with valid point
    frame = valid_frame

    # Final decision: turn right if heading is positive, left otherwise
    return frame, "right" if observation["views"][frame]["heading"] > 0 else "left", {"heading": observation["views"][frame]["heading"]}

